import {background,hunter,monster} from './art.js';import {MONSTERS} from './content.js';
const descriptions=['竹丛随风轻摆，岩石蜥蜴爬行、停顿与甩尾。','霜降草轻摆，灯笼乌贼在后方潮汐浅水带缓缓游动。','火药草点缀石缝，Echobat 小群间歇掠过洞顶。'];
const canvases=MONSTERS.map((m,i)=>{const section=document.createElement('section'),h=document.createElement('h2'),p=document.createElement('p'),canvas=document.createElement('canvas');h.textContent=m.area;p.textContent=descriptions[i];canvas.width=960;canvas.height=360;canvas.setAttribute('aria-label',m.area+'动态背景');section.append(h,p,canvas);document.querySelector('#scenes').append(section);return canvas;});
let time=6,last=0,playing=true;const camera=document.querySelector('#camera'),actors=document.querySelector('#actors');document.querySelector('#play').onclick=e=>{playing=!playing;e.target.textContent=playing?'暂停背景':'播放背景';};
function frame(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;if(playing)time+=dt;canvases.forEach((canvas,i)=>{const c=canvas.getContext('2d');c.save();c.scale(2,2);c.imageSmoothingEnabled=false;const g=background(c,480,180,i,time,Number(camera.value));if(actors.checked){hunter(c,180,g,'female','ls',1,0);monster(c,310,g,MONSTERS[i].id,-1,0);}c.restore();});requestAnimationFrame(frame);}requestAnimationFrame(frame);
